import datetime

# FAQデータベース
faq_database = [
    {
        'question': '初心者でも大丈夫ですか?',
        'answer': 'もちろんです! 初心者大歓迎です。基礎から丁寧に教えます。',
        'tags': ['初心者', '参加']
    },
    {
        'question': '参加費は必要ですか?',
        'answer': '完全無料です! 気軽にご参加ください。',
        'tags': ['料金', '参加費']
    },
    {
        'question': 'どうやって勉強すればいいですか?',
        'answer': '毎週の勉強会に参加したり、#質問チャンネルで質問したりできます!',
        'tags': ['勉強', '学習']
    },
    {
        'question': 'Pythonのインストール方法は?',
        'answer': 'python.org から最新版をダウンロードしてインストールしてください。詳細は #初心者ガイド で!',
        'tags': ['インストール', 'Python']
    }
]

# コマンド定義
commands = {
    '!help': '''📚 利用可能なコマンド:
├─ !help      - このヘルプを表示
├─ !faq       - よくある質問を表示
├─ !event     - イベント情報
├─ !stats     - ボット統計を表示
└─ !welcome   - ウェルカムメッセージを表示''',

    '!faq': 'FAQ一覧',  # 動的に生成
    '!event': '📅 次回イベント: 1月15日 20:00 - Python勉強会',
    '!stats': 'ボット統計',  # 動的に生成
    '!welcome': 'ウェルカムメッセージ'  # 動的に生成
}

class AdvancedChatBot:
    def __init__(self):
        self.message_count = 0
        self.command_count = 0
        self.start_time = datetime.datetime.now()

    def search_faq(self, query):
        '''FAQを検索'''
        results = []
        query_lower = query.lower()

        for faq in faq_database:
            # 質問文またはタグにマッチ
            if query_lower in faq['question'].lower():
                results.append(faq)
            else:
                for tag in faq['tags']:
                    if tag in query_lower:
                        results.append(faq)
                        break

        return results

    def get_faq_list(self):
        '''FAQ一覧を取得'''
        response = '❓ よくある質問 (FAQ):\n\n'
        for i, faq in enumerate(faq_database, 1):
            response += f'{i}. {faq["question"]}\n   💡 {faq["answer"]}\n\n'
        return response

    def welcome_message(self, member_name='新メンバー'):
        '''ウェルカムメッセージを生成'''
        return f'''🎉 ようこそ {member_name}さん!

Python学習コミュニティへようこそ!

📍 まずはここをチェック:
• #ルール でサーバールールを確認
• #自己紹介 で自己紹介してね
• !help でコマンド一覧を確認

質問は気軽に #質問 チャンネルでどうぞ!
楽しく学びましょう! 🐍✨'''

    def get_stats(self):
        '''ボット統計を取得'''
        uptime = datetime.datetime.now() - self.start_time
        hours = int(uptime.total_seconds() // 3600)
        minutes = int((uptime.total_seconds() % 3600) // 60)

        return f'''📊 ボット統計情報:

🤖 稼働時間: {hours}時間 {minutes}分
💬 処理メッセージ数: {self.message_count}件
⚡ コマンド実行回数: {self.command_count}回
📚 FAQ登録数: {len(faq_database)}件
✅ ステータス: 正常稼働中'''

    def process_message(self, author, content):
        '''メッセージを処理'''
        self.message_count += 1

        # コマンド処理
        if content.startswith('!'):
            self.command_count += 1
            command = content.split()[0].lower()

            if command == '!faq':
                return self.get_faq_list()
            elif command == '!stats':
                return self.get_stats()
            elif command == '!welcome':
                return self.welcome_message(author)
            elif command in commands:
                return commands[command]

        # FAQ検索
        if '?' in content or '質問' in content:
            faq_results = self.search_faq(content)
            if faq_results:
                response = '❓ 関連するFAQが見つかりました:\n\n'
                for faq in faq_results[:2]:  # 最大2件
                    response += f'Q: {faq["question"]}\nA: {faq["answer"]}\n\n'
                return response

        # キーワード自動返信
        keywords = {
            'ありがとう': 'どういたしまして! 😊',
            'こんにちは': 'こんにちは! 👋',
            'おはよう': 'おはようございます! ☀️',
            'こんばんは': 'こんばんは! 🌙'
        }

        for keyword, response in keywords.items():
            if keyword in content:
                return response

        return None

# デモ実行
def run_advanced_bot_demo():
    bot = AdvancedChatBot()

    test_messages = [
        ('太郎', '!help'),
        ('花子', 'こんにちは'),
        ('次郎', '初心者でも大丈夫ですか?'),
        ('さくら', '!faq'),
        ('健太', '!welcome'),
        ('美咲', 'ありがとう'),
        ('翔太', 'Pythonのインストール方法を教えて'),
        ('あい', '!stats')
    ]

    print('\n' + '=' * 70)
    print('🤖 高度なチャットボット - デモ'.center(70))
    print('=' * 70)

    for author, content in test_messages:
        print(f'\n👤 {author}: {content}')
        response = bot.process_message(author, content)

        if response:
            print(f'🤖 ボット:\n{response}')
        else:
            print('🤖 ボット: (反応なし)')

        print('─' * 70)

    print('\n' + '=' * 70)
    print('✅ デモ完了')
    print('=' * 70)

run_advanced_bot_demo()
